Given an array arr[] of non-negative integers which may contain duplicate elements. Return the frequency of each distinct element present in the array.Examples: Input:  arr[] = [10, 20, 10, 5, 20]Output: [[5, 1], [10, 2], [20, 2]]Explanation: Here 5 occurs once, 10 occurs 2 times and 20 occurs 2 times.Input: arr[] = [10, 20, 20]Output: [[10, 1], [20, 2]] Explanation: Here 10 occurs 1 time, 20 occurs 2 times.Try It YourselfTable of Content[Naive Approach] Brute Force - O(n^2) Time O(n) Space[Better Approach] Using binary search[Expected Solution] Using hashing - O(n) Time and O(n) Space[Naive Approach] Brute Force - O(n2) Time O(n) SpaceA simple solution is to run two loops. For every item count number of times, it occurs. To avoid duplicate printing, keep track of processed items.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<vector<int>> countFreq(vector<int>& arr){
    int n = arr.size();

    // Mark all array elements as not visited
    vector<bool> visited(n , false);
    vector<vector<int>>ans;
    for (int i = 0; i < n; i++) {

        // Skip this element if already processed
        if (visited[i] == true)
            continue;

        // store the frequency
        int count = 1;
        for (int j = i + 1; j < n; j++) {
            if (arr[i] == arr[j]) {
                visited[j] = true;
                count++;
            }

        }
        ans.push_back({arr[i] , count});
    }
    return ans;
}

int main(){
    vector <int> arr = {10, 20, 10, 5, 20};
    vector<vector<int>>ans =  countFreq(arr);
    sort(ans.begin(), ans.end()) ;
    for (auto x : ans){
        cout << x[0] << ' '<< x[1] <<'\n';
    }
    return 0 ;
}


