Time Complexity: O(n × log2n) , where O(log2n) time for binary search function.Auxiliary Space: O(1), as using constant extra space [Expected Solution] Using hashing - O(n) Time and O(n) SpaceAn efficient solution  is using  a hash map (e.g. unordered_map in C++, HashMap in Java, dict in Python, or Dictionary in C#), we can store elements as keys and their frequencies as values.
            C++

    #include <iostream>
#include <unordered_map>
#include <vector>
#include <algorithm>
using namespace std;

vector<vector<int>> countFreq(vector<int>& arr) {

    // stores frequency of each number
    unordered_map<int, int> mp;      
    // stores {number, frequency}
    vector<vector<int>> ans;         

    // count frequency using unordered_map
    for (int num : arr) {
        mp[num]++;
    }

    // build the answer vector from the frequency map
    for (auto &it : mp) {
        ans.push_back({it.first, it.second});
    }

    return ans ;
}

int main() {
    vector<int> arr = {10, 20, 10, 5, 20};

    vector<vector<int>> ans = countFreq(arr);

    // sort the result in ascending order of the number
    sort(ans.begin(), ans.end(), [](vector<int>& a, 
                        vector<int>& b) {
        return a[0] < b[0];  
    });

    for (auto &x : ans) {
        cout << x[0] << " " << x[1] << endl;
    }

    return 0;
}


